expr:
(
  rate(container_cpu_usage_seconds_total{namespace="mereka-lms", pod=~"enterprise-catalog-.*", container="enterprise-catalog"}[5m])
  / container_spec_cpu_quota{namespace="mereka-lms", pod=~"enterprise-catalog-.*", container="enterprise-catalog"}
  * container_spec_cpu_period{namespace="mereka-lms", pod=~"enterprise-catalog-.*", container="enterprise-catalog"}
) > 0.85

(
  rate(container_cpu_usage_seconds_total{namespace="mereka-lms", pod=~"enterprise-access-.*", container="enterprise-access"}[5m])
  / container_spec_cpu_quota{namespace="mereka-lms", pod=~"enterprise-access-.*", container="enterprise-access"}
  * container_spec_cpu_period{namespace="mereka-lms", pod=~"enterprise-access-.*", container="enterprise-access"}
) > 0.85

(
  rate(container_cpu_usage_seconds_total{namespace="mereka-lms", pod=~"enterprise-subsidy-.*", container="enterprise-subsidy"}[5m])
  / container_spec_cpu_quota{namespace="mereka-lms", pod=~"enterprise-subsidy-.*", container="enterprise-subsidy"}
  * container_spec_cpu_period{namespace="mereka-lms", pod=~"enterprise-subsidy-.*", container="enterprise-subsidy"}
) > 0.85

(
  rate(container_cpu_usage_seconds_total{namespace="mereka-lms", pod=~"license-manager-.*", container="license-manager"}[5m])
  / container_spec_cpu_quota{namespace="mereka-lms", pod=~"license-manager-.*", container="license-manager"}
  * container_spec_cpu_period{namespace="mereka-lms", pod=~"license-manager-.*", container="license-manager"}
) > 0.85

(
  rate(container_cpu_usage_seconds_total{namespace="mereka-lms", pod=~"lms-.*", container="lms"}[5m])
  / container_spec_cpu_quota{namespace="mereka-lms", pod=~"lms-.*", container="lms"}
  * container_spec_cpu_period{namespace="mereka-lms", pod=~"lms-.*", container="lms"}
) > 0.85

container_memory_swap{job="kubelet", metrics_path="/metrics/cadvisor", image!=""}
* on (cluster, namespace, pod) group_left(node) topk by (cluster, namespace, pod) (1,
  max by (cluster, namespace, pod, node) (kube_pod_info{node!=""})
)

sum(rate(kubelet_evictions{job="kubelet", metrics_path="/metrics"}[15m])) by (cluster, eviction_signal, instance)
* on (cluster, instance) group_left(node)
max by (cluster, instance, node) (
  kubelet_node_name{job="kubelet", metrics_path="/metrics"}
)
> 0

count by (cluster, node) (
  node_cpu_seconds_total{mode="idle",job="node-exporter"}
  * on (cluster, namespace, pod) group_left(node)
  topk by (cluster, namespace, pod) (1, node_namespace_pod:kube_pod_info:)
)
